        foreground_app = str(getattr(observation, "foreground_app", "") or "")
        foreground_window = str(getattr(observation, "foreground_window", "") or "")
        combined = f"{foreground_app}\n{foreground_window}".casefold()
        self._record(
            metadata,
            "final_ui.textedit_foreground",
            any(value in combined for value in expected),
            {"foreground_app_any": expected},
            {"foreground_app": foreground_app, "foreground_window": foreground_window},
            "Final foreground app/window is not TextEdit in the macOS1 guest",
        )


